-- READ-ONLY exact-key aggregate; excludes protected Q1 2018; UTC bounds.
WITH c AS (SELECT CASE WHEN o.dateTime<1530403200 THEN '2018-Q2' WHEN o.dateTime<1538352000 THEN '2018-Q3' ELSE '2018-Q4' END AS utc_quarter,o.usUnits AS ou,w.usUnits AS wu,o.interval AS oi,w.interval AS wi,o.`soilTemp4` AS old_soilTemp4, w.`soilTemp4` AS wh_soilTemp4, o.`supplyVoltage` AS old_supplyVoltage, w.`supplyVoltage` AS wh_supplyVoltage, o.`txBatteryStatus` AS old_txBatteryStatus, w.`txBatteryStatus` AS wh_txBatteryStatus, o.`windBatteryStatus` AS old_windBatteryStatus, w.`windBatteryStatus` AS wh_windBatteryStatus, o.`windDir` AS old_windDir, w.`windDir` AS wh_windDir, o.`windGust` AS old_windGust, w.`windGust` AS wh_windGust, o.`windGustDir` AS old_windGustDir, w.`windGustDir` AS wh_windGustDir, o.`windSpeed` AS old_windSpeed, w.`windSpeed` AS wh_windSpeed, o.`windchill` AS old_windchill, w.`windchill` AS wh_windchill FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1522540800 AND o.dateTime<1546300800 AND r.dateTime IS NULL) SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'soilTemp4' AS field_name,COUNT(*) AS source_only_rows,SUM(old_soilTemp4 IS NOT NULL) AS old_nonnull,SUM(wh_soilTemp4 IS NOT NULL) AS wh_nonnull,SUM(old_soilTemp4 IS NOT NULL AND wh_soilTemp4 IS NOT NULL AND old_soilTemp4<=>wh_soilTemp4) AS paired_equal,SUM(old_soilTemp4 IS NOT NULL AND wh_soilTemp4 IS NOT NULL AND NOT(old_soilTemp4<=>wh_soilTemp4)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'supplyVoltage' AS field_name,COUNT(*) AS source_only_rows,SUM(old_supplyVoltage IS NOT NULL) AS old_nonnull,SUM(wh_supplyVoltage IS NOT NULL) AS wh_nonnull,SUM(old_supplyVoltage IS NOT NULL AND wh_supplyVoltage IS NOT NULL AND old_supplyVoltage<=>wh_supplyVoltage) AS paired_equal,SUM(old_supplyVoltage IS NOT NULL AND wh_supplyVoltage IS NOT NULL AND NOT(old_supplyVoltage<=>wh_supplyVoltage)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'txBatteryStatus' AS field_name,COUNT(*) AS source_only_rows,SUM(old_txBatteryStatus IS NOT NULL) AS old_nonnull,SUM(wh_txBatteryStatus IS NOT NULL) AS wh_nonnull,SUM(old_txBatteryStatus IS NOT NULL AND wh_txBatteryStatus IS NOT NULL AND old_txBatteryStatus<=>wh_txBatteryStatus) AS paired_equal,SUM(old_txBatteryStatus IS NOT NULL AND wh_txBatteryStatus IS NOT NULL AND NOT(old_txBatteryStatus<=>wh_txBatteryStatus)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windBatteryStatus' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windBatteryStatus IS NOT NULL) AS old_nonnull,SUM(wh_windBatteryStatus IS NOT NULL) AS wh_nonnull,SUM(old_windBatteryStatus IS NOT NULL AND wh_windBatteryStatus IS NOT NULL AND old_windBatteryStatus<=>wh_windBatteryStatus) AS paired_equal,SUM(old_windBatteryStatus IS NOT NULL AND wh_windBatteryStatus IS NOT NULL AND NOT(old_windBatteryStatus<=>wh_windBatteryStatus)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windDir' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windDir IS NOT NULL) AS old_nonnull,SUM(wh_windDir IS NOT NULL) AS wh_nonnull,SUM(old_windDir IS NOT NULL AND wh_windDir IS NOT NULL AND old_windDir<=>wh_windDir) AS paired_equal,SUM(old_windDir IS NOT NULL AND wh_windDir IS NOT NULL AND NOT(old_windDir<=>wh_windDir)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windGust' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windGust IS NOT NULL) AS old_nonnull,SUM(wh_windGust IS NOT NULL) AS wh_nonnull,SUM(old_windGust IS NOT NULL AND wh_windGust IS NOT NULL AND old_windGust<=>wh_windGust) AS paired_equal,SUM(old_windGust IS NOT NULL AND wh_windGust IS NOT NULL AND NOT(old_windGust<=>wh_windGust)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windGustDir' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windGustDir IS NOT NULL) AS old_nonnull,SUM(wh_windGustDir IS NOT NULL) AS wh_nonnull,SUM(old_windGustDir IS NOT NULL AND wh_windGustDir IS NOT NULL AND old_windGustDir<=>wh_windGustDir) AS paired_equal,SUM(old_windGustDir IS NOT NULL AND wh_windGustDir IS NOT NULL AND NOT(old_windGustDir<=>wh_windGustDir)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windSpeed' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windSpeed IS NOT NULL) AS old_nonnull,SUM(wh_windSpeed IS NOT NULL) AS wh_nonnull,SUM(old_windSpeed IS NOT NULL AND wh_windSpeed IS NOT NULL AND old_windSpeed<=>wh_windSpeed) AS paired_equal,SUM(old_windSpeed IS NOT NULL AND wh_windSpeed IS NOT NULL AND NOT(old_windSpeed<=>wh_windSpeed)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi UNION ALL SELECT utc_quarter,oi AS old_interval,wi AS wh_interval,'windchill' AS field_name,COUNT(*) AS source_only_rows,SUM(old_windchill IS NOT NULL) AS old_nonnull,SUM(wh_windchill IS NOT NULL) AS wh_nonnull,SUM(old_windchill IS NOT NULL AND wh_windchill IS NOT NULL AND old_windchill<=>wh_windchill) AS paired_equal,SUM(old_windchill IS NOT NULL AND wh_windchill IS NOT NULL AND NOT(old_windchill<=>wh_windchill)) AS paired_conflict,SUM(ou<>wu) AS unit_conflict_rows,SUM(oi<>wi) AS interval_conflict_rows FROM c GROUP BY utc_quarter,oi,wi
ORDER BY utc_quarter,old_interval,wh_interval,field_name\n